-- Custom SQL (WS3, not generated by drizzle-kit) -----------------------------------------------------------------
-- EFF-4: re-index full text only when an indexed column changes. Refreshes that only touch fetched_at, meta,
-- kind or source_class no longer delete and re-tokenize the whole document.
DROP TRIGGER IF EXISTS `sources_fts_au`;--> statement-breakpoint
CREATE TRIGGER `sources_fts_au` AFTER UPDATE OF `title`, `content_md` ON `sources` BEGIN
  INSERT INTO `sources_fts`(`sources_fts`, rowid, `title`, `content_md`) VALUES ('delete', old.rowid, old.`title`, old.`content_md`);
  INSERT INTO `sources_fts`(rowid, `title`, `content_md`) VALUES (new.rowid, new.`title`, new.`content_md`);
END;--> statement-breakpoint
-- EFF-9: content_len mirrors length(content_md) for every writer (knowledge base, agent tools, admin), so
-- overviews and admin summaries never read the content itself.
CREATE TRIGGER `sources_len_ai` AFTER INSERT ON `sources` BEGIN
  UPDATE `sources` SET `content_len` = length(new.`content_md`) WHERE rowid = new.rowid;
END;--> statement-breakpoint
CREATE TRIGGER `sources_len_au` AFTER UPDATE OF `content_md` ON `sources` BEGIN
  UPDATE `sources` SET `content_len` = length(new.`content_md`) WHERE rowid = new.rowid;
END;--> statement-breakpoint
UPDATE `sources` SET `content_len` = length(`content_md`);--> statement-breakpoint
-- SRC-1/SRC-9: knowledge bases built before deterministic classification hold docs relabelled as marketing and
-- junk labelled independent. Mark them stale so the next evaluation rebuilds them (old rows are pruned by run id).
UPDATE `projects` SET `kb_refreshed_at` = NULL WHERE `kb_status` = 'ready';
